// Generated by `node bundle.js`, paste this whole file into the Cloudflare dashboard editor.

const modes = ['solid', 'gradient', 'rainbow', 'pulse'];
const roles = ['', 'owner', 'staff'];

const roleOk = (role) => roles.includes(role);

const nameOk = (name) => typeof name === 'string' && /^[A-Za-z0-9 _.-]{1,32}$/.test(name) && name.trim() === name;

const keyOf = (name) => name.toLowerCase();

// A free tag must not read like a badge that only the service hands out.
const badges = ['owner', 'staff', 'team', 'admin', 'mod', 'moderator', 'dev', 'developer', 'support', 'official'];

function tagReserved(tag) {
  const plain = tag.toLowerCase().replace(/[^a-z]/g, '').replace(/^(monchi|mochi)/, '');
  return badges.includes(plain);
}

const hex = (value, fallback) => (typeof value === 'string' && /^#[0-9a-fA-F]{6}$/.test(value) ? value.toLowerCase() : fallback);

function cleanStyle(raw) {
  const s = raw && typeof raw === 'object' ? raw : {};
  const mode = modes.includes(s.mode) ? s.mode : 'solid';
  const speed = Math.min(5, Math.max(0.1, Number.isFinite(s.speed) ? s.speed : 1));
  return {
    mode,
    a: hex(s.a, '#3ba7ec'),
    b: hex(s.b, '#ffffff'),
    speed: Math.round(speed * 100) / 100,
    heartColor: hex(s.heartColor, '#3ba7ec'),
    tag: typeof s.tag === 'string' ? [...s.tag].filter(c => c.codePointAt(0) >= 0x20 && c.codePointAt(0) !== 167).slice(0, 32).join('') : '',
    tagColor: hex(s.tagColor, '#3ba7ec'),
    heart: s.heart !== false,
  };
}

function cleanWorn(raw) {
  if (!Array.isArray(raw)) return [];
  const out = [];
  for (const item of raw) {
    if (out.length >= 12) break;
    if (!item || typeof item.id !== 'string' || !/^[a-z0-9_]{1,40}$/.test(item.id)) continue;
    const tint = Array.isArray(item.tint) ? item.tint.slice(0, 8).map((c) => hex(c, '#ffffff')) : [];
    out.push({ id: item.id, tint });
  }
  return out;
}

function cleanServer(raw) {
  if (typeof raw !== 'string') return '';
  return [...raw].filter((c) => c.codePointAt(0) >= 0x20).slice(0, 48).join('').trim();
}

const row = (r) => (r ? { ...r, style: JSON.parse(r.style), worn: JSON.parse(r.worn), visible: !!r.visible, role: r.role ?? '' } : null);

// db: { one(sql, args), all(sql, args), run(sql, args), batch([[sql, args], ...]) }
function sqlStore(db, counts = new Map()) {
  // databases created before roles existed get the column the first time they are used
  let migrated = false;
  async function migrate() {
    if (migrated) return;
    migrated = true;
    try {
      await db.run("ALTER TABLE players ADD COLUMN role TEXT NOT NULL DEFAULT ''", []);
    } catch {
      // the column is already there
    }
  }

  return {
    async player(key) {
      await migrate();
      return row(await db.one('SELECT * FROM players WHERE key = ?', [key]));
    },
    async savePlayer(p) {
      await migrate();
      await db.run(
        `INSERT INTO players (key, name, secret, style, worn, visible, server, client, seen, created, role)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT(key) DO UPDATE SET name = excluded.name, secret = excluded.secret, style = excluded.style, worn = excluded.worn,
           visible = excluded.visible, server = excluded.server, client = excluded.client, seen = excluded.seen, role = excluded.role`,
        [p.key, p.name, p.secret, JSON.stringify(p.style), JSON.stringify(p.worn), p.visible ? 1 : 0, p.server, p.client, p.seen, p.created, p.role ?? ''],
      );
    },
    async removePlayer(key) {
      await db.batch([
        ['DELETE FROM sessions WHERE key = ?', [key]],
        ['DELETE FROM players WHERE key = ?', [key]],
      ]);
    },
    async session(token) {
      return db.one('SELECT key, expires FROM sessions WHERE token = ?', [token]);
    },
    async saveSession(token, key, expires) {
      await db.batch([
        ['INSERT OR REPLACE INTO sessions (token, key, expires) VALUES (?, ?, ?)', [token, key, expires]],
        ['DELETE FROM sessions WHERE key = ? AND token NOT IN (SELECT token FROM sessions WHERE key = ? ORDER BY expires DESC LIMIT 3)', [key, key]],
      ]);
    },
    async removeSession(token) {
      await db.run('DELETE FROM sessions WHERE token = ?', [token]);
    },
    async lookup(keys, since) {
      if (!keys.length) return [];
      const marks = keys.map(() => '?').join(',');
      const rows = await db.all(`SELECT * FROM players WHERE key IN (${marks}) AND visible = 1 AND seen >= ?`, [...keys, since]);
      return rows.map(row);
    },
    async count(since) {
      const r = await db.one('SELECT COUNT(*) AS n FROM players WHERE visible = 1 AND seen >= ?', [since]);
      return r ? Number(r.n) : 0;
    },
    async isBlocked(key) {
      return !!(await db.one('SELECT 1 AS x FROM blocked WHERE key = ?', [key]));
    },
    async block(key, reason) {
      await db.batch([
        ['INSERT OR REPLACE INTO blocked (key, reason) VALUES (?, ?)', [key, reason]],
        ['DELETE FROM sessions WHERE key = ?', [key]],
        ['DELETE FROM players WHERE key = ?', [key]],
      ]);
    },
    async hit(bucket, limit, windowSec, now) {
      const slot = `${bucket}:${Math.floor(now / windowSec)}`;
      const n = (counts.get(slot) ?? 0) + 1;
      counts.set(slot, n);
      if (counts.size > 5000) counts.clear();
      return n <= limit;
    },
    async sweep(before) {
      await db.batch([
        ["DELETE FROM players WHERE seen < ? AND role = ''", [before]],
        ['DELETE FROM sessions WHERE expires < ?', [before]],
      ]);
    },
  };
}


const limiters = new WeakMap();

function d1Store(env) {
  const d1 = env.DB;
  if (!limiters.has(d1)) limiters.set(d1, new Map());
  const stmt = (sql, args = []) => d1.prepare(sql).bind(...args);
  return sqlStore(
    {
      one: (sql, args) => stmt(sql, args).first(),
      all: async (sql, args) => (await stmt(sql, args).all()).results,
      run: (sql, args) => stmt(sql, args).run(),
      batch: (list) => d1.batch(list.map(([sql, args]) => stmt(sql, args))),
    },
    limiters.get(d1),
  );
}


const online = 300;
const sessionTtl = 12 * 3600;
const reclaimAfter = 30 * 86400;
const maxBody = 16 * 1024;
const minAdminKey = 24;

const json = (data, status = 200) =>
  new Response(JSON.stringify(data), { status, headers: { 'content-type': 'application/json', 'cache-control': 'no-store' } });

const fail = (status, error) => json({ error }, status);

const hexOf = (bytes) => [...new Uint8Array(bytes)].map((b) => b.toString(16).padStart(2, '0')).join('');

async function sha256(text) {
  return hexOf(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text)));
}

function randomToken() {
  return hexOf(crypto.getRandomValues(new Uint8Array(32)));
}

async function readBody(request) {
  if (Number(request.headers.get('content-length') ?? 0) > maxBody) return { error: 413 };
  const reader = request.body?.getReader();
  const decoder = new TextDecoder('utf-8', { fatal: true });
  let text = '', size = 0;
  try {
    if (reader) {
      for (;;) {
        const { value, done } = await reader.read();
        if (done) break;
        size += value.byteLength;
        if (size > maxBody) {
          await reader.cancel();
          return { error: 413 };
        }
        text += decoder.decode(value, { stream: true });
      }
      text += decoder.decode();
    }
  } catch {
    await reader?.cancel().catch(() => {});
    return { error: 400 };
  } finally {
    reader?.releaseLock();
  }
  if (!text) return { body: {} };
  try {
    const body = JSON.parse(text);
    return body && typeof body === 'object' && !Array.isArray(body) ? { body } : { error: 400 };
  } catch {
    return { error: 400 };
  }
}

async function authed(request, store, now) {
  const header = request.headers.get('authorization') ?? '';
  const token = header.startsWith('Bearer ') ? header.slice(7).trim() : '';
  if (!/^[0-9a-f]{64}$/.test(token)) return null;
  const hash = await sha256(token);
  const session = await store.session(hash);
  if (!session || session.expires < now) return null;
  const player = await store.player(session.key);
  if (!player) return null;
  if (session.expires - now < sessionTtl / 2) await store.saveSession(hash, session.key, now + sessionTtl);
  return { player, hash };
}

async function hello(body, ip, store, now) {
  if (!(await store.hit(`hello:${ip}`, 10, 60, now))) return fail(429, 'slow down');
  if (!nameOk(body.name)) return fail(400, 'name');
  if (typeof body.secret !== 'string' || !/^[0-9a-f]{48}$/.test(body.secret)) return fail(400, 'secret');
  const key = keyOf(body.name);
  if (await store.isBlocked(key)) return fail(403, 'blocked');

  const secret = await sha256(body.secret);
  const existing = await store.player(key);
  const same = existing && existing.secret === secret;
  // a name that carries a role is never handed to another install, however long it has been silent
  if (existing && !same && (existing.role || now - existing.seen < reclaimAfter)) return fail(403, 'claimed');
  // nobody proves that a gamertag is theirs, so one address only gets to take a few names a day
  if (!same && !(await store.hit(`claim:${ip}`, 10, 86400, now))) return fail(429, 'slow down');

  const style = cleanStyle(body.style);
  if (!(same && existing.role) && tagReserved(style.tag)) style.tag = '';
  const player = {
    key,
    name: body.name,
    secret,
    style,
    worn: cleanWorn(body.worn),
    visible: body.visible !== false,
    server: '',
    client: typeof body.client === 'string' ? body.client.slice(0, 16) : '',
    seen: now,
    created: same ? existing.created : now,
    role: same ? existing.role ?? '' : '',
  };
  await store.savePlayer(player);

  const token = randomToken();
  await store.saveSession(await sha256(token), key, now + sessionTtl);
  return json({ token, ttl: sessionTtl, style, worn: player.worn, role: player.role });
}

async function profile(body, auth, store, now) {
  const style = cleanStyle(body.style ?? auth.player.style);
  if (!auth.player.role && tagReserved(style.tag)) style.tag = '';
  const player = {
    ...auth.player,
    style,
    worn: body.worn === undefined ? auth.player.worn : cleanWorn(body.worn),
    visible: body.visible === undefined ? auth.player.visible : body.visible !== false,
    seen: now,
  };
  await store.savePlayer(player);
  return json({ style, worn: player.worn });
}

async function presence(body, auth, store, now) {
  await store.savePlayer({ ...auth.player, server: cleanServer(body.server), seen: now });
  return json({ ok: true });
}

async function lookup(body, auth, store, now) {
  const names = Array.isArray(body.names) ? body.names.filter(nameOk).slice(0, 100) : [];
  const keys = [...new Set(names.map(keyOf))];
  const found = await store.lookup(keys, now - online);
  const users = found.map((p) => ({ name: p.name, style: p.style, worn: p.worn, role: p.role ?? '' }));
  return json({ users });
}

async function bye(auth, store, now) {
  await store.removeSession(auth.hash);
  await store.savePlayer({ ...auth.player, server: '', seen: Math.min(auth.player.seen, now - online - 1) });
  return json({ ok: true });
}

async function forget(auth, store) {
  await store.removePlayer(auth.player.key);
  return json({ ok: true });
}

async function isAdmin(request, env) {
  const given = request.headers.get('x-admin-key') ?? '';
  // a short key could be guessed by trying; such a key switches the admin calls off instead
  if (!env.ADMIN_KEY || env.ADMIN_KEY.length < minAdminKey) return false;
  return given.length === env.ADMIN_KEY.length && (await sha256(given)) === (await sha256(env.ADMIN_KEY));
}

async function admin(request, body, store, env) {
  if (!(await isAdmin(request, env))) return fail(403, 'no');
  if (!nameOk(body.name)) return fail(400, 'name');
  await store.block(keyOf(body.name), typeof body.reason === 'string' ? body.reason.slice(0, 200) : '');
  return json({ ok: true });
}

// A role sticks to the install that holds the gamertag, and a gamertag with a role cannot be reclaimed by another one.
async function setRole(request, body, store, env) {
  if (!(await isAdmin(request, env))) return fail(403, 'no');
  if (!nameOk(body.name)) return fail(400, 'name');
  const role = body.role ?? '';
  if (!roleOk(role)) return fail(400, 'role');
  const player = await store.player(keyOf(body.name));
  if (!player) return fail(404, 'unknown');
  await store.savePlayer({ ...player, role });
  return json({ ok: true, name: player.name, role });
}

async function handle(request, env, store, now = Math.floor(Date.now() / 1000)) {
  const url = new URL(request.url);
  const path = url.pathname.replace(/\/+$/, '');

  if (path === '/v1/health') return json({ ok: true, online: await store.count(now - online) });
  if (request.method !== 'POST') return fail(405, 'method');

  const read = await readBody(request);
  if (read.error) return fail(read.error, 'body');
  const body = read.body;
  const ip = request.headers.get('cf-connecting-ip') ?? 'local';

  if (path === '/v1/hello') return hello(body, ip, store, now);
  if (path.startsWith('/v1/admin/') && !(await store.hit(`admin:${ip}`, 5, 60, now))) return fail(429, 'slow down');
  if (path === '/v1/admin/block') return admin(request, body, store, env);
  if (path === '/v1/admin/role') return setRole(request, body, store, env);

  const auth = await authed(request, store, now);
  if (!auth) return fail(401, 'token');
  if (!(await store.hit(`${path}:${auth.player.key}`, 30, 60, now))) return fail(429, 'slow down');

  switch (path) {
    case '/v1/profile':
      return profile(body, auth, store, now);
    case '/v1/presence':
      return presence(body, auth, store, now);
    case '/v1/lookup':
      return lookup(body, auth, store, now);
    case '/v1/bye':
      return bye(auth, store, now);
    case '/v1/forget':
      return forget(auth, store);
    default:
      return fail(404, 'route');
  }
}

async function sweep(store, now = Math.floor(Date.now() / 1000)) {
  await store.sweep(now - 90 * 86400);
}


export default {
  fetch(request, env) {
    return handle(request, env, d1Store(env));
  },
  scheduled(event, env, ctx) {
    ctx.waitUntil(sweep(d1Store(env)));
  },
};
